+    load: usize,
+    matches: usize,
+    minimum: usize,
+    slack: usize,
+    best_load: usize,
+    best_matches: usize,
+) -> bool {
+    load <= minimum.saturating_add(slack)
+        && (matches > best_matches || matches == best_matches && load < best_load)
