+    pub async fn query_scalar<R: FromSqlOwned, T>(
+        &self,
+        statement: &T,
+        params: &[&(dyn ToSql + Sync)],
+    ) -> Result<Vec<R>, Error>
+    where
+        T: ?Sized + ToStatement + fmt::Debug,
+    {
+        let rows: Vec<Row> = self
+            .query_raw(statement, slice_iter(params))
+            .await?
+            .try_collect()
+            .await?;
+
+        if let Some(row) = rows.first() {
+            if row.len() != 1 {
