+struct BorrowToSqlParamsDebug<'a, T>(&'a [T]);
+
+impl<T> fmt::Debug for BorrowToSqlParamsDebug<'_, T>
+where
+    T: BorrowToSql,
+{
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.debug_list()
+            .entries(self.0.iter().map(|x| x.borrow_to_sql()))
+            .finish()
+    }
+}
+
+pub async fn query<P, I>(
+    client: &InnerClient,
+    statement: Statement,
+    params: I,
+) -> Result<RowStream, Error>
+where
+    P: BorrowToSql,
+    I: IntoIterator<Item = P>,
+    I::IntoIter: ExactSizeIterator,
+{
+    let buf = if log_enabled!(Level::Debug) {
+        let params = params.into_iter().collect::<Vec<_>>();
+        debug!(
+            "executing statement {} with parameters: {:?}",
+            statement.name(),
+            BorrowToSqlParamsDebug(params.as_slice()),
+        );
+        encode(client, &statement, params)?
+    } else {
+        encode(client, &statement, params)?
+    };
+    let responses = start(client, buf).await?;
+    Ok(RowStream {
+        statement,
+        responses,
+        rows_affected: None,
+    })
+}
+
+pub async fn query_typed<P, I>(
+    client: &Arc<InnerClient>,
+    query: &str,
+    params: I,
+) -> Result<RowStream, Error>
+where
+    P: BorrowToSql,
+    I: IntoIterator<Item = (P, Type)>,
+{
+    let buf = {
+        let params = params.into_iter().collect::<Vec<_>>();
+        let param_oids = params.iter().map(|(_, t)| t.oid()).collect::<Vec<_>>();
+
+        client.with_buf(|buf| {
+            frontend::parse("", query, param_oids, buf).map_err(Error::parse)?;
+            encode_bind_raw("", params, "", buf)?;
+            frontend::describe(b'S', "", buf).map_err(Error::encode)?;
+            frontend::execute("", 0, buf).map_err(Error::encode)?;
+            frontend::sync(buf);
+
+            Ok(buf.split().freeze())
+        })?
+    };
+
+    let mut responses = client.send(RequestMessages::Single(FrontendMessage::Raw(buf)))?;
+
+    loop {
+        match responses.next().await? {
+            Message::ParseComplete | Message::BindComplete | Message::ParameterDescription(_) => {}
+            Message::NoData => {
+                return Ok(RowStream {
+                    statement: Statement::unnamed(vec![], vec![]),
+                    responses,
+                    rows_affected: None,
+                });
+            }
+            Message::RowDescription(row_description) => {
+                let mut columns: Vec<Column> = vec![];
+                let mut it = row_description.fields();
+                while let Some(field) = it.next().map_err(Error::parse)? {
+                    let type_ = get_type(client, field.type_oid()).await?;
+                    let column = Column {
+                        name: field.name().to_string(),
+                        table_oid: Some(field.table_oid()).filter(|n| *n != 0),
+                        column_id: Some(field.column_id()).filter(|n| *n != 0),
+                        type_modifier: field.type_modifier(),
+                        r#type: type_,
+                    };
+                    columns.push(column);
+                }
+                return Ok(RowStream {
+                    statement: Statement::unnamed(vec![], columns),
+                    responses,
+                    rows_affected: None,
+                });
+            }
+            _ => return Err(Error::unexpected_message()),
+        }
+    }
+}
+
+pub async fn execute_typed<P, I>(
+    client: &Arc<InnerClient>,
+    query: &str,
+    params: I,
+) -> Result<u64, Error>
+where
+    P: BorrowToSql,
+    I: IntoIterator<Item = (P, Type)>,
+{
+    let buf = {
+        let params = params.into_iter().collect::<Vec<_>>();
+        let param_oids = params.iter().map(|(_, t)| t.oid()).collect::<Vec<_>>();
+
+        client.with_buf(|buf| {
+            frontend::parse("", query, param_oids, buf).map_err(Error::parse)?;
+            encode_bind_raw("", params, "", buf)?;
+            frontend::describe(b'S', "", buf).map_err(Error::encode)?;
+            frontend::execute("", 0, buf).map_err(Error::encode)?;
+            frontend::sync(buf);
+
+            Ok(buf.split().freeze())
+        })?
+    };
+
+    let mut responses = client.send(RequestMessages::Single(FrontendMessage::Raw(buf)))?;
+
+    let mut rows = 0;
+
+    loop {
+        match responses.next().await? {
+            Message::ParseComplete
+            | Message::BindComplete
+            | Message::ParameterDescription(_)
+            | Message::RowDescription(_) => {}
+            Message::NoData => {
+                rows = 0;
+            }
+
+            Message::DataRow(_) => {}
+            Message::CommandComplete(body) => {
+                rows = extract_row_affected(&body)?;
+            }
+
+            Message::EmptyQueryResponse => rows = 0,
+            Message::ReadyForQuery(_) => return Ok(rows),
+            _ => {
+                return Err(Error::unexpected_message());
+            }
+        }
+    }
+}
+
+pub async fn query_portal(
+    client: &InnerClient,
+    portal: &Portal,
+    max_rows: i32,
+) -> Result<RowStream, Error> {
+    let buf = client.with_buf(|buf| {
+        frontend::execute(portal.name(), max_rows, buf).map_err(Error::encode)?;
+        frontend::sync(buf);
+        Ok(buf.split().freeze())
+    })?;
+
+    let responses = client.send(RequestMessages::Single(FrontendMessage::Raw(buf)))?;
+
+    Ok(RowStream {
+        statement: portal.statement().clone(),
+        responses,
+        rows_affected: None,
+    })
+}
+
+/// Extract the number of rows affected from [`CommandCompleteBody`].
+pub fn extract_row_affected(body: &CommandCompleteBody) -> Result<u64, Error> {
+    let rows = body
+        .tag()
+        .map_err(Error::parse)?
+        .rsplit(' ')
+        .next()
+        .unwrap()
+        .parse()
+        .unwrap_or(0);
+    Ok(rows)
+}
+
+pub async fn execute<P, I>(
+    client: &InnerClient,
+    statement: Statement,
+    params: I,
+) -> Result<u64, Error>
+where
+    P: BorrowToSql,
+    I: IntoIterator<Item = P>,
+    I::IntoIter: ExactSizeIterator,
+{
+    let buf = if log_enabled!(Level::Debug) {
+        let params = params.into_iter().collect::<Vec<_>>();
+        debug!(
+            "executing statement {} with parameters: {:?}",
+            statement.name(),
+            BorrowToSqlParamsDebug(params.as_slice()),
+        );
+        encode(client, &statement, params)?
+    } else {
+        encode(client, &statement, params)?
+    };
+    let mut responses = start(client, buf).await?;
+
+    let mut rows = 0;
+    loop {
+        match responses.next().await? {
+            Message::DataRow(_) => {}
+            Message::CommandComplete(body) => {
+                rows = extract_row_affected(&body)?;
+            }
+            Message::EmptyQueryResponse => rows = 0,
+            Message::ReadyForQuery(_) => return Ok(rows),
+            _ => return Err(Error::unexpected_message()),
+        }
+    }
+}
+
+async fn start(client: &InnerClient, buf: Bytes) -> Result<Responses, Error> {
+    let mut responses = client.send(RequestMessages::Single(FrontendMessage::Raw(buf)))?;
+
+    match responses.next().await? {
+        Message::BindComplete => {}
+        _ => return Err(Error::unexpected_message()),
+    }
+
+    Ok(responses)
+}
+
+pub fn encode<P, I>(client: &InnerClient, statement: &Statement, params: I) -> Result<Bytes, Error>
+where
+    P: BorrowToSql,
+    I: IntoIterator<Item = P>,
+    I::IntoIter: ExactSizeIterator,
+{
+    client.with_buf(|buf| {
+        encode_bind(statement, params, "", buf)?;
+        frontend::execute("", 0, buf).map_err(Error::encode)?;
+        frontend::sync(buf);
+        Ok(buf.split().freeze())
+    })
+}
+
+pub fn encode_bind<P, I>(
+    statement: &Statement,
+    params: I,
+    portal: &str,
+    buf: &mut BytesMut,
+) -> Result<(), Error>
+where
+    P: BorrowToSql,
+    I: IntoIterator<Item = P>,
+    I::IntoIter: ExactSizeIterator,
+{
+    let params = params.into_iter();
+    if params.len() != statement.params().len() {
+        return Err(Error::parameters(params.len(), statement.params().len()));
+    }
+
+    encode_bind_raw(
+        statement.name(),
+        params.zip(statement.params().iter().cloned()),
+        portal,
+        buf,
+    )
+}
+
+fn encode_bind_raw<P, I>(
+    statement_name: &str,
+    params: I,
+    portal: &str,
+    buf: &mut BytesMut,
+) -> Result<(), Error>
+where
+    P: BorrowToSql,
+    I: IntoIterator<Item = (P, Type)>,
+    I::IntoIter: ExactSizeIterator,
+{
+    let (param_formats, params): (Vec<_>, Vec<_>) = params
+        .into_iter()
+        .map(|(p, ty)| (p.borrow_to_sql().encode_format(&ty) as i16, (p, ty)))
+        .unzip();
+
+    let mut error_idx = 0;
+    let r = frontend::bind(
+        portal,
+        statement_name,
+        param_formats,
+        params.into_iter().enumerate(),
+        |(idx, (param, ty)), buf| match param.borrow_to_sql().to_sql_checked(&ty, buf) {
+            Ok(IsNull::No) => Ok(postgres_protocol::IsNull::No),
+            Ok(IsNull::Yes) => Ok(postgres_protocol::IsNull::Yes),
+            Err(e) => {
+                error_idx = idx;
+                Err(e)
+            }
+        },
+        Some(1),
+        buf,
+    );
+    match r {
+        Ok(()) => Ok(()),
+        Err(frontend::BindError::Conversion(e)) => Err(Error::to_sql(e, error_idx)),
+        Err(frontend::BindError::Serialization(e)) => Err(Error::encode(e)),
+    }
+}
+
+pin_project! {
+    /// A stream of table rows.
+    #[project(!Unpin)]
+    pub struct RowStream {
+        statement: Statement,
+        responses: Responses,
+        rows_affected: Option<u64>,
+    }
+}
+
+impl Stream for RowStream {
+    type Item = Result<Row, Error>;
+
+    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
+        let this = self.project();
+        loop {
+            match ready!(this.responses.poll_next(cx)?) {
+                Message::DataRow(body) => {
+                    return Poll::Ready(Some(Ok(Row::new(this.statement.clone(), body)?)));
+                }
+                Message::CommandComplete(body) => {
+                    *this.rows_affected = Some(extract_row_affected(&body)?);
+                }
+                Message::EmptyQueryResponse | Message::PortalSuspended => {}
+                Message::ReadyForQuery(_) => return Poll::Ready(None),
+                _ => return Poll::Ready(Some(Err(Error::unexpected_message()))),
+            }
+        }
+    }
+}
+
+impl RowStream {
+    /// Returns the number of rows affected by the query.
+    ///
+    /// This function will return `None` until the stream has been exhausted.
+    pub fn rows_affected(&self) -> Option<u64> {
+        self.rows_affected
+    }
+}
+
+pub async fn sync(client: &InnerClient) -> Result<(), Error> {
+    let buf = Bytes::from_static(b"S\0\0\0\x04");
+    let mut responses = client.send(RequestMessages::Single(FrontendMessage::Raw(buf)))?;
+
+    match responses.next().await? {
+        Message::ReadyForQuery(_) => Ok(()),
+        _ => Err(Error::unexpected_message()),
+    }
+}
+
+// Used only by the application's exclusively owned read actors. No statement is
+// retried in the driver, and a failed batch is fully drained before returning.
+pub async fn query_group(
+    client: &InnerClient,
+    requests: &[(&Statement, Vec<&(dyn crate::types::ToSql + Sync)>)],
+) -> Result<Vec<Vec<Row>>, Error> {
+    if requests.is_empty() { return Ok(Vec::new()); }
+    let buf = client.with_buf(|buf| {
+        for (statement, params) in requests {
+            encode_bind(statement, params.iter().copied(), "", buf)?;
+            frontend::execute("", 0, buf).map_err(Error::encode)?;
+        }
+        frontend::sync(buf);
+        Ok(buf.split().freeze())
+    })?;
+    let mut responses = client.send(RequestMessages::Single(FrontendMessage::Raw(buf)))?;
+    let mut rows: Vec<Vec<Row>> = requests.iter().map(|_| Vec::new()).collect();
+    let mut current = 0;
+    let mut failure = None;
+    loop {
+        match responses.next().await {
+            Ok(Message::BindComplete) => {},
+            Ok(Message::DataRow(body)) if current < requests.len() => {
+                match Row::new(requests[current].0.clone(), body) {
+                    Ok(row) => rows[current].push(row),
+                    Err(e) => { if failure.is_none() { failure = Some(e); } }
+                }
+            },
+            Ok(Message::CommandComplete(_)) if current < requests.len() => current += 1,
+            Ok(Message::ReadyForQuery(_)) => {
+                if let Some(e) = failure { return Err(e); }
+                return if current == requests.len() { Ok(rows) } else { Err(Error::unexpected_message()) };
+            },
+            Err(e) => {
+                if e.as_db_error().is_none() { return Err(e); }
+                if failure.is_none() { failure = Some(e); }
+            },
+            Ok(_) => { if failure.is_none() { failure = Some(Error::unexpected_message()); } },
+        }
+    }
+}
+
+pub fn encode_group_query(statement: &Statement, params: &[&(dyn crate::types::ToSql + Sync)]) -> Result<Bytes, Error> {
+    let mut buf = BytesMut::with_capacity(128);
+    encode_bind(statement, params.iter().copied(), "", &mut buf)?;
+    frontend::execute("", 0, &mut buf).map_err(Error::encode)?;
+    Ok(buf.freeze())
+}
+pub async fn query_group_encoded(client: &InnerClient, requests: &[(&Statement, Bytes)]) -> Result<Vec<Vec<Row>>, Error> {
+    if requests.is_empty() { return Ok(Vec::new()); }
+    let buf = client.with_buf(|buf| {
+        for (_, bytes) in requests { buf.extend_from_slice(bytes); }
+        frontend::sync(buf);
+        Ok::<_, Error>(buf.split().freeze())
+    })?;
+    let mut responses = client.send(RequestMessages::Single(FrontendMessage::Raw(buf)))?;
+    let mut rows: Vec<Vec<Row>> = requests.iter().map(|_| Vec::new()).collect();
+    let mut current = 0;
+    let mut failure = None;
+    loop {
+        match responses.next().await {
+            Ok(Message::BindComplete) => {},
+            Ok(Message::DataRow(body)) if current < requests.len() => {
+                match Row::new(requests[current].0.clone(), body) {
+                    Ok(row) => rows[current].push(row),
+                    Err(e) => { if failure.is_none() { failure = Some(e); } }
+                }
+            },
+            Ok(Message::CommandComplete(_)) if current < requests.len() => current += 1,
+            Ok(Message::ReadyForQuery(_)) => {
+                if let Some(e) = failure { return Err(e); }
+                return if current == requests.len() { Ok(rows) } else { Err(Error::unexpected_message()) };
+            },
+            Err(e) => {
+                if e.as_db_error().is_none() { return Err(e); }
+                if failure.is_none() { failure = Some(e); }
+            },
+            Ok(_) => { if failure.is_none() { failure = Some(Error::unexpected_message()); } },
+        }
+    }
